/* Review only: renders the Death Star product patterns in system.html with the product's own helpers. */
(() => {
  const DS = window.DS; if (!DS) return;
  const { D, ui, icon, esc } = DS;
  const c = D.cById.marchetti;
  const S = {
    trust: () => ['verified', 'single', 'stale', 'disputed'].map(k => ui.trust(k)).join(''),
    classes: () => ['A', 'B', 'C', 'D', 'LH'].map(k => ui.cls(k)).join('') + ['A', 'B'].map(k => ui.cls(k, true)).join(''),
    chips: () => ui.scoreChip('Score 132', 132) + `<span class="ds-chip" data-tone="outline"><span class="ds-dot" data-tone="active"></span>Contacted</span><span class="ds-chip">Tier 1 · Hot</span><span class="ds-chip" data-tone="danger">${icon('warning-diamond')}Asked not to be contacted</span><span class="ds-filter-chip">${icon('funnel-simple')}Lower East Side</span><span class="ds-outtag" data-o="Interested">Interested</span><span class="ds-outtag" data-o="Callback">Callback</span><span class="ds-sev" data-sev="Critical">Critical</span><span class="ds-sev" data-sev="Strong">Strong</span>`,
    shell: () => `<div class="sys-shellbar"><span class="ds-wordmark" style="flex:none">Death Star</span><nav class="ds-crumbs" aria-label="Example breadcrumb"><a href="#patterns">Database</a>${icon('caret-right')}<span aria-current="page">Daniel Marchetti</span></nav><button type="button" class="ds-search-trigger" style="width:15rem">${icon('magnifying-glass')}<span>Search contacts, properties, BBL</span><kbd>⌘K</kbd></button><button type="button" class="ds-ask" aria-pressed="false">${icon('sparkle')}Ask Brain<span class="ds-ask__dot"></span></button><button type="button" class="ds-ask" aria-pressed="true">${icon('sparkle')}Ask Brain</button></div><div class="sys-shellnav"><a class="ds-nav" aria-current="page" href="#patterns">${icon('house')}<span>Home</span></a><a class="ds-nav" href="#patterns">${icon('squares-four')}<span>Dashboard</span></a><span class="ds-nav-group" role="presentation"><span>Channels</span>${icon('caret-down')}</span><a class="ds-nav" role="link" tabindex="0" aria-disabled="true" data-tip="${DS.OFF}">${icon('envelope-simple')}<span>Email</span><span class="ds-nav__badge">4</span></a></div>`,
    why: () => `<section class="ds-why"><div class="ds-why__head">${icon('sparkle')}<h2>Why now</h2>${ui.trust('verified')}<span class="ds-grow"></span><span class="ds-meta">Updated 2d ago</span></div><p class="ds-why__text">${esc(c.whyFull)}</p><div class="ds-why__actions">${ui.btn({ label: 'Next: Call (212) 555-0147', ic: 'phone', variant: 'subtle', shape: 'pill' })}<span class="ds-grow"></span>${ui.btn({ label: 'Why this?', variant: 'outline' })}${ui.btn({ label: 'Ask Brain', ic: 'sparkle', variant: 'outline' })}</div></section>`,
    evidence: () => `<div class="ds-stack" data-gap="2">${D.evidence(c).slice(0, 3).concat([D.evidence(c)[5]]).map(([l, v, m, k]) => `<div class="ds-evidence"><div class="ds-row__body"><span><span class="font-medium">${esc(l)}</span><span class="muted"> · ${esc(v)}</span></span><span class="ds-meta">${esc(m)}</span></div>${ui.trust(k)}${k === 'disputed' ? '<span></span>' : ui.btn({ label: 'Flag as wrong', variant: 'ghost', size: 'sm' })}</div>`).join('')}</div>`,
    callnext: () => ['marchetti', 'feld'].map((id, i) => { const x = D.cById[id]; return `<div class="ds-callrow"${i ? ' data-done' : ''}>${ui.cls(x.cls)}<a class="ds-callrow__name" href="#patterns"><b>${esc(x.name)}</b><span class="ds-row__sub">${esc(D.pById[x.pid].addr)}</span></a><span class="ds-callrow__why">${esc(x.why)}</span>${ui.trust(x.trust)}${i ? `<span class="ds-called">${icon('check')}</span>` : `<button type="button" class="button button--icon" data-variant="outline" aria-label="Call">${icon('phone')}</button>`}</div>`; }).join(''),
    pulse: () => `<div class="ds-pulse">${[['Calls today', 'phone', '6', 'of 40', 0.15, '+2 vs. yesterday', 'up'], ['Follow-ups due', 'clock', '1', 'today', 0, '2 overdue', 'warn']].map(([l, i, v, of, r, d, t]) => `<a class="ds-pulse__cell" href="#patterns"><span class="ds-pulse__label"><span class="ds-tile-icon" data-tone="tint">${icon(i)}</span>${l}</span><span class="ds-pulse__value"><b>${v}</b><span class="ds-meta">${of}</span></span>${ui.progress(r, l, { thin: true, fill: true })}<span class="ds-delta" data-tone="${t}">${icon(t === 'up' ? 'arrow-up-right' : 'warning-circle')}${d}</span></a>`).join('')}</div>`,
    chart: () => { const t = D.tiles[0]; return `<div class="ds-card" data-pad="lg">${ui.bars(t.vals, t.labels, { max: t.max, goal: t.goal, zero: t.zero, aria: t.title })}</div>`; },
    live: () => `<div class="ds-livebar" style="position:static;border-radius:var(--radius-lg)"><span class="ds-livebar__dot"></span><span class="font-medium">On a call with Daniel Marchetti</span><span class="ds-livebar__num">(212) 555-0147</span><span class="ds-grow"></span><span class="ds-livebar__time">1:14</span>${ui.btn({ label: 'End call', ic: 'phone-disconnect' })}</div><div class="ds-outcome" style="margin-top:var(--space-3)"><h2>Log the outcome</h2><div class="ds-outcome__opts">${['Connected', 'Callback', 'Voicemail', 'No answer', 'Not interested', 'Bad number'].map(o => `<button type="button" class="ds-opt" role="radio" aria-checked="${o === 'No answer'}">${o}</button>`).join('')}</div><div class="ds-toolbar">${ui.btn({ label: 'Save outcome' })}${ui.btn({ label: 'Skip', variant: 'outline' })}</div></div>`,
    brain: () => `<div class="ds-brain" style="width:auto"><div class="ds-brain__head">${icon('sparkle')}<b>Brain</b></div><div class="ds-chat"><div class="ds-msg-user">Why now for Daniel Marchetti?</div><div class="ds-msg-bot"><div class="ds-msg-bot__text">${esc(c.whyFull)}</div><div class="ds-answer"><div style="display:flex;align-items:center;gap:var(--space-2)">${ui.cls('A')}<b class="ds-grow">Daniel Marchetti</b>${ui.trust('verified')}</div><div class="ds-toolbar">${ui.btn({ label: 'Call', ic: 'phone', size: 'sm' })}${ui.btn({ label: 'Open record', size: 'sm', variant: 'outline' })}</div></div></div><div class="ds-think">${['Finding the owner', 'Reading the evidence', 'Writing the why now'].map((t, i) => `<span class="ds-think__step" data-state="${['done', 'now', 'todo'][i]}">${icon(['check-circle', 'circle-notch', 'circle'][i])}${t}</span>`).join('')}</div></div>${DS.composer(false)}</div>`,
    events: () => `<div class="ds-toolbar" style="align-items:stretch">${[['mtg', 'Lunch · Grace Okafor', '12 PM – 1 PM'], ['call', 'Calls · LES maturities', '1:30 PM – 3 PM'], ['tour', 'Tour · 41 Ludlow St', '9:30 AM – 10:30 AM'], ['mkt', 'Mail merge · Listings', '10 AM – 11 AM']].map(([k, t, tm], i) => `<button type="button" class="ds-ev" data-cal="${k}" aria-pressed="${i === 1}" style="position:relative;width:11rem;height:3rem"><b><span class="ds-ev-dot"></span>${t}</b><span>${tm}</span></button>`).join('')}</div><div style="max-width:17rem;margin-top:var(--space-3)"><a class="ds-conv" href="#patterns"><span style="display:flex;align-items:center;gap:var(--space-2)">${ui.cls('B')}<b class="ds-grow">Ruth Adler</b></span><span style="color:var(--fg-secondary)">Open to a pricing opinion on 64 Essex St</span><span class="ds-conv__foot"><span class="ds-outtag" data-o="Interested">Interested</span><span class="ds-meta">Send comps Fri</span></span></a></div>`,
  };
  const draw = () => document.querySelectorAll('[data-sample]').forEach(el => { const f = S[el.dataset.sample]; if (f) el.innerHTML = f(); });
  draw();
})();
